import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Quote {
  text: string;
  source: string;
  author: string;
}

export interface Level {
  name: string;
  minXP: number;
}

export interface GameState {
  xp: number;
  completedQuotes: number;
}

export enum GameStatus {
  IDLE = 'IDLE',
  PLAYING = 'PLAYING',
  COMPLETED = 'COMPLETED', // Successfully typed with 100% accuracy
  FAILED = 'FAILED', // Typed but mistakes were present at the end
}

import { Level } from '../types';

export const LEVELS: Level[] = [
  { name: 'Egg III', minXP: 0 },
  { name: 'Egg II', minXP: 700 },
  { name: 'Egg I', minXP: 1400 },
  { name: 'Tadpole III', minXP: 2100 },
  { name: 'Tadpole II', minXP: 3600 },
  { name: 'Tadpole I', minXP: 5100 },
  { name: 'Polliwog III', minXP: 6600 },
  { name: 'Polliwog II', minXP: 8900 },
  { name: 'Polliwog I', minXP: 11200 },
  { name: 'Froglet III', minXP: 13600 },
  { name: 'Froglet II', minXP: 17000 },
  { name: 'Froglet I', minXP: 20500 },
  { name: 'Hopper III', minXP: 24000 },
  { name: 'Hopper II', minXP: 33000 },
  { name: 'Hopper I', minXP: 42000 },
  { name: 'Tree Frog III', minXP: 50000 },
  { name: 'Tree Frog II', minXP: 67000 },
  { name: 'Tree Frog I', minXP: 83000 },
  { name: 'Bullfrog', minXP: 100000 },
  { name: 'Frog Sage', minXP: 150000 }, // Cap for display purposes
];

export const getCurrentLevel = (xp: number): Level => {
  // Find the highest level where xp >= minXP
  for (let i = LEVELS.length - 1; i >= 0; i--) {
    if (xp >= LEVELS[i].minXP) {
      return LEVELS[i];
    }
  }
  return LEVELS[0];
};

export const getNextLevel = (currentLevel: Level): Level | null => {
  const index = LEVELS.indexOf(currentLevel);
  if (index >= 0 && index < LEVELS.length - 1) {
    return LEVELS[index + 1];
  }
  return null; // Max level reached
};

export const calculateXP = (wpm: number, length: number): number => {
  // Logic: XP = Typing speed * number of letters typed
  return Math.floor(wpm * length);
};

import { GoogleGenAI, Type } from "@google/genai";
import { Quote } from '../types';

const FALLBACK_QUOTES: Quote[] = [
  {
    text: "The unexamined life is not worth living.",
    source: "Philosophy",
    author: "Socrates"
  },
  {
    text: "For God has not given us a spirit of fear, but of power and of love and of a sound mind.",
    source: "Bible",
    author: "2 Timothy 1:7"
  },
  {
    text: "We did not send down the Quran to you to cause you any hardship.",
    source: "Quran",
    author: "Rashad Khalifa Translation (20:2)"
  },
  {
    text: "I think, therefore I am.",
    source: "Philosophy",
    author: "René Descartes"
  },
  {
    text: "Love is patient, love is kind. It does not envy, it does not boast, it is not proud.",
    source: "Bible",
    author: "1 Corinthians 13:4"
  }
];

let ai: GoogleGenAI | null = null;
if (process.env.API_KEY) {
  ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
}

export const fetchQuotes = async (count: number = 3): Promise<Quote[]> => {
  if (!ai) {
    console.warn("No API Key found, using fallback quotes.");
    // Return a random shuffle of fallback quotes
    return [...FALLBACK_QUOTES].sort(() => 0.5 - Math.random());
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Generate ${count} diverse and wisdom-filled quotes.
      Sources MUST be strictly from:
      1. Rashad Khalifa's authorized English translation of the Quran (God speaking).
      2. The Bible (Wisdom verses).
      3. Famous Philosophers (Stoicism, Greek, etc).

      Keep quotes between 50 and 200 characters.
      Ensure accuracy in attribution.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              text: { type: Type.STRING },
              source: { type: Type.STRING, description: "E.g., Quran, Bible, Philosophy" },
              author: { type: Type.STRING, description: "Specific author or verse reference" }
            },
            required: ["text", "source", "author"]
          }
        }
      }
    });

    if (response.text) {
      const data = JSON.parse(response.text);
      if (Array.isArray(data)) {
        return data as Quote[];
      }
    }
    return FALLBACK_QUOTES;
  } catch (error) {
    console.error("Error fetching quotes from Gemini:", error);
    return FALLBACK_QUOTES;
  }
};

import React from 'react';
import { Level, GameState } from '../types';
import { getCurrentLevel, getNextLevel } from '../utils/gameLogic';

interface ProgressBarProps {
  xp: number;
}

const ProgressBar: React.FC<ProgressBarProps> = ({ xp }) => {
  const currentLevel = getCurrentLevel(xp);
  const nextLevel = getNextLevel(currentLevel);

  let progressPercent = 100;
  let nextLevelName = 'Max Level';

  if (nextLevel) {
    const xpInLevel = xp - currentLevel.minXP;
    const levelSpan = nextLevel.minXP - currentLevel.minXP;
    progressPercent = Math.min(100, Math.max(0, (xpInLevel / levelSpan) * 100));
    nextLevelName = nextLevel.name;
  }

  return (
    <div className="w-full max-w-2xl mx-auto mb-8 px-4">
      <div className="flex justify-between items-end mb-2 text-stone-600">
        <div className="flex flex-col">
          <span className="text-xs font-bold uppercase tracking-wider text-stone-400">Current Rank</span>
          <span className="text-xl font-bold text-frog-700">{currentLevel.name}</span>
        </div>
        <div className="text-right flex flex-col items-end">
           <span className="text-xs font-bold uppercase tracking-wider text-stone-400">Next Rank</span>
           <span className="text-sm font-semibold text-stone-500">{nextLevelName}</span>
        </div>
      </div>

      <div className="relative h-4 bg-stone-200 rounded-full overflow-hidden shadow-inner">
        <div 
          className="absolute top-0 left-0 h-full bg-frog-500 transition-all duration-500 ease-out rounded-full"
          style={{ width: `${progressPercent}%` }}
        />
      </div>

      <div className="flex justify-between mt-1 text-xs text-stone-400 font-mono">
        <span>{xp.toLocaleString()} XP</span>
        {nextLevel && <span>{nextLevel.minXP.toLocaleString()} XP</span>}
      </div>
    </div>
  );
};

export default ProgressBar;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Quote, GameStatus } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { Play, RotateCcw, Award } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number) => void;
  onRequestNewQuote: () => void;
}

const TypingArea: React.FC<TypingAreaProps> = ({ quote, onComplete, onRequestNewQuote }) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Reset state when quote changes
  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    // Automatically focus when new quote loads if already focused on container
    if (isFocused) {
        inputRef.current?.focus();
    }
  }, [quote, isFocused]);

  const handleFocus = () => {
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    // Only blur if we click outside the main container area
    // This is handled by the click handler on the overlay, 
    // but the actual blur event on textarea needs to trigger the state change
    // We use a small timeout to allow re-focusing if clicking within the app
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };

    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;

    // WPM calculation: (characters / 5) / minutes
    // Avoid division by zero
    if (durationInMinutes <= 0) return { currentWpm: 0 };

    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);
      }, 500);
      return () => clearInterval(interval);
    }
  }, [status, calculateStats]);

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED) return;

    const val = e.target.value;

    // Start timer on first char
    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(Date.now());
      setStatus(GameStatus.PLAYING);
    }

    setInput(val);

    // Check completion
    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(Date.now());

      if (isPerfect) {
        setStatus(GameStatus.COMPLETED);
        // Calculate final XP
        const finalTime = Date.now();
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        const xp = calculateXP(finalWpm, quote.text.length);
        setWpm(finalWpm);
        // Delay slightly to show completion state before moving on?
        // No, user needs to click "Next" or we trigger it. 
        // Let's trigger it immediately but show a success state.
        // Actually, let's wait for user to hit Enter or show a button, 
        // but the prompt says "Pass a quote". 
        // I'll show a "Success" overlay.
      } else {
        setStatus(GameStatus.FAILED);
      }
    }
  };

  const handleRetry = () => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    inputRef.current?.focus();
  };

  const handleNext = () => {
    const xp = calculateXP(wpm, quote.text.length);
    onComplete(xp);
  };

  // Render characters with coloring
  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = 'text-stone-300'; // Untyped

      if (index < input.length) {
        if (input[index] === char) {
          colorClass = 'text-frog-800'; // Correct
        } else {
          colorClass = 'text-red-500 bg-red-100'; // Incorrect
        }
      }

      return (
        <span key={index} className={`${colorClass} transition-colors duration-100`}>
          {char}
        </span>
      );
    });
  };

  return (
    <div 
      className="relative w-full max-w-3xl mx-auto min-h-[400px] flex flex-col"
      ref={containerRef}
    >
      {/* Focus Overlay */}
      {!isFocused && (
        <div 
          onClick={handleFocus}
          className="absolute inset-0 z-50 flex items-center justify-center bg-white/60 backdrop-blur-sm cursor-pointer rounded-2xl border-2 border-stone-200 shadow-sm transition-all hover:bg-white/40"
        >
          <div className="text-center animate-bounce text-frog-600">
            <Play className="w-12 h-12 mx-auto mb-2 opacity-80" fill="currentColor" />
            <span className="font-bold text-lg tracking-wide">Click to Focus</span>
          </div>
        </div>
      )}

      {/* Main Game Area */}
      <div className={`
        relative flex-grow flex flex-col justify-center p-8 md:p-12 bg-white rounded-3xl shadow-xl transition-all duration-300
        ${!isFocused ? 'blur-[2px]' : ''}
        ${status === GameStatus.FAILED ? 'border-2 border-red-200' : 'border-2 border-transparent'}
        ${status === GameStatus.COMPLETED ? 'border-2 border-frog-400 bg-frog-50' : ''}
      `}>

        {/* Source Header */}
        <div className="absolute top-6 left-8 right-8 flex justify-between text-xs font-bold text-stone-400 uppercase tracking-widest select-none">
          <span>{quote.source}</span>
          <span>{quote.author}</span>
        </div>

        {/* Text Display */}
        <div 
          className="font-mono text-2xl md:text-3xl leading-relaxed break-words mb-8 relative z-10"
          onClick={() => inputRef.current?.focus()}
        >
          {renderText()}
          {/* Blinking Cursor logic roughly */}
          {status !== GameStatus.COMPLETED && isFocused && (
            <span className="caret-blink w-[2px] h-[1em] bg-frog-600 inline-block align-middle ml-[1px] translate-y-[-2px]"></span>
          )}
        </div>

        {/* Hidden Input */}
        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          onBlur={handleBlur}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none"
          autoFocus={isFocused}
          disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        {/* Status Bar */}
        <div className="absolute bottom-6 left-8 right-8 flex justify-between items-center select-none">
           <div className="flex items-center gap-4 text-stone-500 font-mono text-sm">
             <div className="flex flex-col">
                <span className="text-[10px] uppercase font-bold text-stone-300">Speed</span>
                <span className="font-bold text-lg">{wpm} <small className="text-xs">WPM</small></span>
             </div>
             {status === GameStatus.COMPLETED && (
                 <div className="flex flex-col animate-pulse text-frog-600">
                    <span className="text-[10px] uppercase font-bold text-frog-400">XP Earned</span>
                    <span className="font-bold text-lg">+{calculateXP(wpm, quote.text.length)}</span>
                 </div>
             )}
           </div>

           <div>
              {status === GameStatus.FAILED && (
                <button 
                  onClick={handleRetry}
                  className="flex items-center gap-2 px-4 py-2 bg-red-100 text-red-600 rounded-full hover:bg-red-200 transition font-bold text-sm"
                >
                  <RotateCcw className="w-4 h-4" /> Retry
                </button>
              )}
              {status === GameStatus.COMPLETED && (
                <button 
                  onClick={handleNext}
                  className="flex items-center gap-2 px-6 py-2 bg-frog-500 text-white rounded-full hover:bg-frog-600 transition shadow-lg shadow-frog-200 font-bold text-sm"
                >
                  Next Quote <Award className="w-4 h-4" />
                </button>
              )}
           </div>
        </div>
      </div>

      <div className="text-center mt-4 text-stone-400 text-xs">
        {status === GameStatus.FAILED ? "100% Accuracy Required. Try again." : "Type the quote above exactly."}
      </div>
    </div>
  );
};

export default TypingArea;

import React, { useState, useEffect, useCallback } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import { Quote } from './types';
import { fetchQuotes } from './services/geminiService';
import { Loader2 } from 'lucide-react';

const App: React.FC = () => {
  const [xp, setXp] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_xp');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);
  const [currentQuote, setCurrentQuote] = useState<Quote | null>(null);
  const [loading, setLoading] = useState(true);

  // Persist XP
  useEffect(() => {
    localStorage.setItem('frogType_xp', xp.toString());
  }, [xp]);

  const loadMoreQuotes = useCallback(async () => {
    try {
      const newQuotes = await fetchQuotes(5);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (error) {
      console.error("Failed to load quotes", error);
    }
  }, []);

  // Initial Load
  useEffect(() => {
    const init = async () => {
      setLoading(true);
      await loadMoreQuotes();
      setLoading(false);
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Set current quote if null and queue has items
  useEffect(() => {
    if (!currentQuote && quotesQueue.length > 0) {
      const next = quotesQueue[0];
      setCurrentQuote(next);
      setQuotesQueue(prev => prev.slice(1));
    }

    // Low buffer warning
    if (quotesQueue.length < 3 && quotesQueue.length > 0) {
      loadMoreQuotes();
    }
  }, [currentQuote, quotesQueue, loadMoreQuotes]);

  const handleQuoteComplete = (earnedXp: number) => {
    setXp(prev => prev + earnedXp);
    setCurrentQuote(null); // Triggers effect to pop next quote
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#f7f7f5] text-stone-800 font-sans selection:bg-frog-200">
      {/* Header / Nav */}
      <header className="p-6 text-center">
        <h1 className="text-3xl md:text-4xl font-black text-frog-800 tracking-tight flex items-center justify-center gap-2">
          <span>🐸</span> Frog Type
        </h1>
        <p className="text-stone-400 text-sm mt-2 font-medium">Cozy Typing Progression</p>
      </header>

      <main className="flex-grow flex flex-col items-center justify-start pt-4 md:pt-12 px-4 pb-12">
        <ProgressBar xp={xp} />

        <div className="w-full mt-4">
          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center h-[400px] text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p>Hatching quotes...</p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onRequestNewQuote={() => setCurrentQuote(null)}
            />
          ) : (
             <div className="flex flex-col items-center justify-center h-[400px] text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p>Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <footer className="p-6 text-center text-stone-300 text-xs">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

