import React from 'react';
import { Level } from '../types';
import { getCurrentLevel, getNextLevel } from '../utils/gameLogic';

interface ProgressBarProps {
  xp: number;
}

const ProgressBar: React.FC<ProgressBarProps> = ({ xp }) => {
  const currentLevel = getCurrentLevel(xp);
  const nextLevel = getNextLevel(currentLevel);

  let progressPercent = 100;
  let nextLevelName = 'Max';

  if (nextLevel) {
    const xpInLevel = xp - currentLevel.minXP;
    const levelSpan = nextLevel.minXP - currentLevel.minXP;
    progressPercent = Math.min(100, Math.max(0, (xpInLevel / levelSpan) * 100));
    nextLevelName = nextLevel.name;
  }

  return (
    <div className="w-full flex flex-col justify-center">
      <div className="flex justify-between items-end mb-1.5 px-1">
        <div className="flex items-baseline gap-2">
          <span className="text-sm font-bold text-frog-700">{currentLevel.name}</span>
          <span className="text-[10px] text-stone-400 font-mono">{xp.toLocaleString()} XP</span>
        </div>

        <div className="text-right flex items-baseline gap-2">
           <span className="text-[10px] text-stone-300">Next:</span>
           <span className="text-xs font-semibold text-stone-500">{nextLevelName}</span>
        </div>
      </div>

      <div className="relative h-2.5 bg-stone-100 rounded-full overflow-hidden shadow-inner ring-1 ring-stone-200/50">
        <div 
          className="absolute top-0 left-0 h-full bg-frog-400 transition-all duration-700 ease-out rounded-full"
          style={{ width: `${progressPercent}%` }}
        />
      </div>
    </div>
  );
};

