import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Quote, GameStatus } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { Play, RotateCcw, Award } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number) => void;
  onRequestNewQuote: () => void;
}

const TypingArea: React.FC<TypingAreaProps> = ({ quote, onComplete, onRequestNewQuote }) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Reset state when quote changes
  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    // Automatically focus when new quote loads if already focused on container
    if (isFocused) {
        inputRef.current?.focus();
    }
  }, [quote, isFocused]);

  const handleFocus = () => {
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    // Only blur if we click outside the main container area
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };

    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;

    // WPM calculation: (characters / 5) / minutes
    // Avoid division by zero
    if (durationInMinutes <= 0) return { currentWpm: 0 };

    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);
      }, 500);
      return () => clearInterval(interval);
    }
  }, [status, calculateStats]);

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED) return;

    const val = e.target.value;

    // Start timer on first char
    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(Date.now());
      setStatus(GameStatus.PLAYING);
    }

    setInput(val);

    // Check completion
    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(Date.now());

      if (isPerfect) {
        setStatus(GameStatus.COMPLETED);
        // Calculate final XP
        const finalTime = Date.now();
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        const xp = calculateXP(finalWpm, quote.text.length);
        setWpm(finalWpm);
      } else {
        setStatus(GameStatus.FAILED);
      }
    }
  };

  const handleRetry = () => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    inputRef.current?.focus();
  };

  const handleNext = () => {
    const xp = calculateXP(wpm, quote.text.length);
    onComplete(xp);
  };

  // Render characters with coloring
  const renderText = () => {
    return quote.text.split('').map((char, index) => {
      let colorClass = 'text-stone-300'; // Untyped

      if (index < input.length) {
        if (input[index] === char) {
          colorClass = 'text-frog-800'; // Correct
        } else {
          colorClass = 'text-red-500 bg-red-100'; // Incorrect
        }
      }

      return (
        <span key={index} className={`${colorClass} transition-colors duration-100`}>
          {char}
        </span>
      );
    });
  };

  return (
    <div 
      className="relative w-full max-w-3xl mx-auto min-h-[280px] flex flex-col"
      ref={containerRef}
    >
      {/* Focus Overlay - Matches border radius of the card now (rounded-3xl) */}
      {!isFocused && (
        <div 
          onClick={handleFocus}
          className="absolute inset-0 z-50 flex items-center justify-center bg-white/60 backdrop-blur-[2px] cursor-pointer rounded-3xl border-2 border-dashed border-frog-200/50 hover:border-frog-300 transition-all"
        >
          <div className="text-center animate-bounce text-frog-500">
            <Play className="w-8 h-8 mx-auto mb-2 opacity-80" fill="currentColor" />
            <span className="font-bold text-sm tracking-wide uppercase">Click to Start</span>
          </div>
        </div>
      )}

      {/* Main Game Area */}
      <div className={`
        relative flex-grow flex flex-col justify-center p-8 md:p-12 bg-white rounded-3xl shadow-[0_8px_30px_rgb(0,0,0,0.04)] transition-all duration-300
        ${!isFocused ? 'blur-[1px] opacity-50' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-100' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-frog-100 bg-frog-50/30' : ''}
      `}>

        {/* Source Header */}
        <div className="absolute top-6 left-8 right-8 flex justify-between text-[10px] font-bold text-stone-300 uppercase tracking-widest select-none">
          <span>{quote.source}</span>
          <span>{quote.author}</span>
        </div>

        {/* Text Display */}
        <div 
          className="font-mono text-2xl md:text-3xl leading-relaxed break-words mb-10 mt-4 relative z-10 outline-none"
          onClick={() => inputRef.current?.focus()}
        >
          {renderText()}
          {/* Blinking Cursor logic */}
          {status !== GameStatus.COMPLETED && isFocused && (
            <span className="caret-blink w-[3px] h-[1em] bg-frog-400 inline-block align-middle ml-[1px] translate-y-[-2px] rounded-full"></span>
          )}
        </div>

        {/* Hidden Input */}
        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          onBlur={handleBlur}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none"
          autoFocus={isFocused}
          disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        {/* Status Bar */}
        <div className="absolute bottom-6 left-8 right-8 flex justify-between items-end select-none">
           <div className="flex items-center gap-6 text-stone-400 font-mono text-xs">
             <div className="flex flex-col">
                <span className="text-[9px] uppercase font-bold text-stone-300 mb-0.5">Speed</span>
                <span className="font-bold text-base text-stone-600">{wpm} <span className="text-[10px] font-normal">WPM</span></span>
             </div>
             {status === GameStatus.COMPLETED && (
                 <div className="flex flex-col animate-pulse text-frog-600">
                    <span className="text-[9px] uppercase font-bold text-frog-400 mb-0.5">XP Earned</span>
                    <span className="font-bold text-base">+{calculateXP(wpm, quote.text.length)}</span>
                 </div>
             )}
           </div>

           <div>
              {status === GameStatus.FAILED && (
                <button 
                  onClick={handleRetry}
                  className="flex items-center gap-2 px-4 py-1.5 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition font-bold text-xs tracking-wide"
                >
                  <RotateCcw className="w-3 h-3" /> Retry
                </button>
              )}
              {status === GameStatus.COMPLETED && (
                <button 
                  onClick={handleNext}
                  className="flex items-center gap-2 px-5 py-2 bg-frog-500 text-white rounded-full hover:bg-frog-600 transition shadow-lg shadow-frog-200/50 font-bold text-xs tracking-wide"
                >
                  Next Quote <Award className="w-3 h-3" />
                </button>
              )}
           </div>
        </div>
      </div>

      <div className="text-center mt-4 h-4 text-stone-300 text-[10px] transition-opacity duration-500">
        {status === GameStatus.FAILED ? <span className="text-red-300">100% Accuracy Required. Try again.</span> : 
         status === GameStatus.COMPLETED ? <span className="text-frog-400">Perfect! Well done.</span> :
         isFocused ? "Type the quote above exactly." : ""}
      </div>
    </div>
  );
};

export default TypingArea;

