import React, { useState, useEffect, useCallback } from 'react';
import ProgressBar from './components/ProgressBar';
import TypingArea from './components/TypingArea';
import SettingsModal from './components/SettingsModal';
import { Quote, GameSettings } from './types';
import { fetchQuotes } from './services/geminiService';
import { Loader2, Flame, Settings as SettingsIcon } from 'lucide-react';

const App: React.FC = () => {
  const [xp, setXp] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_xp');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [streak, setStreak] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_streak');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [lastWpm, setLastWpm] = useState<number>(() => {
    const saved = localStorage.getItem('frogType_lastWpm');
    return saved ? parseInt(saved, 10) : 0;
  });

  const [settings, setSettings] = useState<GameSettings>(() => {
    const saved = localStorage.getItem('frogType_settings');
    return saved ? JSON.parse(saved) : { ghostMode: false, readAheadMode: false };
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [quotesQueue, setQuotesQueue] = useState<Quote[]>([]);
  const [currentQuote, setCurrentQuote] = useState<Quote | null>(null);
  const [loading, setLoading] = useState(true);

  // Persistence
  useEffect(() => {
    localStorage.setItem('frogType_xp', xp.toString());
  }, [xp]);

  useEffect(() => {
    localStorage.setItem('frogType_streak', streak.toString());
  }, [streak]);

  useEffect(() => {
    localStorage.setItem('frogType_lastWpm', lastWpm.toString());
  }, [lastWpm]);

  useEffect(() => {
    localStorage.setItem('frogType_settings', JSON.stringify(settings));
  }, [settings]);

  const loadMoreQuotes = useCallback(async () => {
    try {
      const newQuotes = await fetchQuotes(5);
      setQuotesQueue(prev => [...prev, ...newQuotes]);
    } catch (error) {
      console.error("Failed to load quotes", error);
    }
  }, []);

  // Initial Load
  useEffect(() => {
    const init = async () => {
      setLoading(true);
      await loadMoreQuotes();
      setLoading(false);
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Set current quote if null and queue has items
  useEffect(() => {
    if (!currentQuote && quotesQueue.length > 0) {
      const next = quotesQueue[0];
      setCurrentQuote(next);
      setQuotesQueue(prev => prev.slice(1));
    }

    // Low buffer warning
    if (quotesQueue.length < 3 && quotesQueue.length > 0) {
      loadMoreQuotes();
    }
  }, [currentQuote, quotesQueue, loadMoreQuotes]);

  const handleQuoteComplete = (earnedXp: number, finalWpm: number) => {
    setXp(prev => prev + earnedXp);
    setStreak(prev => prev + 1);
    setLastWpm(finalWpm);
    setCurrentQuote(null); // Triggers effect to pop next quote
  };

  const handleQuoteFail = () => {
    setStreak(0);
  };

  const toggleSetting = (key: keyof GameSettings) => {
    setSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#f7f7f5] text-stone-800 font-sans selection:bg-frog-200">
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        onToggleSetting={toggleSetting}
      />

      {/* Top Bar Navigation */}
      <header className="w-full bg-white/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-40 px-6 py-4 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-4 md:gap-8">

          {/* Logo & Stats Area */}
          <div className="flex items-center gap-6 w-full md:w-auto justify-between md:justify-start">
             <div className="flex flex-col">
                <h1 className="text-xl font-black text-frog-800 tracking-tight flex items-center gap-2">
                  <span className="text-2xl">🐸</span> Frog Type
                </h1>
             </div>

             {/* Streak Counter */}
             <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full border ${streak > 0 ? 'bg-orange-50 border-orange-200 text-orange-600' : 'bg-stone-50 border-stone-200 text-stone-400'}`}>
                <Flame className={`w-4 h-4 ${streak > 0 ? 'fill-orange-500 animate-pulse' : ''}`} />
                <span className="font-mono font-bold text-sm">{streak}</span>
             </div>
          </div>

          {/* Progress Bar Area */}
          <div className="w-full md:flex-grow md:max-w-2xl">
             <ProgressBar xp={xp} />
          </div>

          {/* Settings Button */}
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="p-2 text-stone-400 hover:bg-stone-100 hover:text-stone-600 rounded-full transition-colors hidden md:block"
          >
            <SettingsIcon className="w-5 h-5" />
          </button>

        </div>
      </header>

      {/* Mobile Settings Button (Absolute) */}
      <button 
        onClick={() => setIsSettingsOpen(true)}
        className="absolute top-4 right-4 p-2 text-stone-400 hover:bg-stone-100 hover:text-stone-600 rounded-full transition-colors md:hidden z-50"
      >
        <SettingsIcon className="w-5 h-5" />
      </button>

      {/* Main Content Area */}
      <main className="flex-grow flex flex-col items-center justify-center p-6 md:p-12 w-full">
        <div className="w-full max-w-4xl flex items-center justify-center min-h-[50vh]">
          {loading && !currentQuote ? (
            <div className="flex flex-col items-center justify-center text-stone-400 animate-pulse">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Hatching quotes...</p>
            </div>
          ) : currentQuote ? (
            <TypingArea 
              quote={currentQuote} 
              onComplete={handleQuoteComplete} 
              onFail={handleQuoteFail}
              onRequestNewQuote={() => setCurrentQuote(null)}
              settings={settings}
              lastWpm={lastWpm}
              streak={streak}
            />
          ) : (
             <div className="flex flex-col items-center justify-center text-stone-400">
              <Loader2 className="w-10 h-10 animate-spin mb-4 text-frog-400" />
              <p className="font-mono text-xs">Fetching wisdom...</p>
            </div>
          )}
        </div>
      </main>

      <footer className="p-6 text-center text-stone-300 text-[10px]">
        <p>© {new Date().getFullYear()} Frog Type. Wisdom from the Ages.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { Quote, GameStatus, GameSettings } from '../types';
import { calculateXP } from '../utils/gameLogic';
import { Play, RotateCcw, Award, Ghost } from 'lucide-react';

interface TypingAreaProps {
  quote: Quote;
  onComplete: (xpEarned: number, wpm: number) => void;
  onFail: () => void;
  onRequestNewQuote: () => void;
  settings: GameSettings;
  lastWpm: number;
  streak: number;
}

const TypingArea: React.FC<TypingAreaProps> = ({ 
  quote, 
  onComplete, 
  onFail, 
  onRequestNewQuote, 
  settings, 
  lastWpm,
  streak 
}) => {
  const [input, setInput] = useState('');
  const [startTime, setStartTime] = useState<number | null>(null);
  const [endTime, setEndTime] = useState<number | null>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [status, setStatus] = useState<GameStatus>(GameStatus.IDLE);
  const [wpm, setWpm] = useState(0);
  const [ghostIndex, setGhostIndex] = useState(0);

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Pre-calculate word boundaries for Read Ahead mode
  const wordBoundaries = useMemo(() => {
    const words: {start: number, end: number}[] = [];
    let currentStart = 0;
    const parts = quote.text.split(/(\s+)/); // Split keeping delimiters

    let index = 0;
    parts.forEach(part => {
      if (part.trim().length > 0) {
        words.push({ start: index, end: index + part.length });
      }
      index += part.length;
    });
    return words;
  }, [quote.text]);

  // Reset state when quote changes
  useEffect(() => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    if (isFocused) {
        inputRef.current?.focus();
    }
  }, [quote, isFocused]);

  // Global keydown listener
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (!isFocused && status !== GameStatus.COMPLETED && status !== GameStatus.FAILED) {
        if (!e.metaKey && !e.altKey && !e.ctrlKey) {
            e.preventDefault(); 
            setIsFocused(true);
            inputRef.current?.focus();
        }
      }
    };

    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [isFocused, status]);

  const handleFocus = () => {
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleBlur = () => {
    setTimeout(() => {
        if (document.activeElement !== inputRef.current) {
            setIsFocused(false);
        }
    }, 100);
  };

  const calculateStats = useCallback(() => {
    if (!startTime) return { currentWpm: 0 };
    const now = endTime || Date.now();
    const durationInMinutes = (now - startTime) / 60000;
    if (durationInMinutes <= 0) return { currentWpm: 0 };
    const currentWpm = Math.round((input.length / 5) / durationInMinutes);
    return { currentWpm };
  }, [endTime, input.length, startTime]);

  // Game Loop (WPM + Ghost)
  useEffect(() => {
    if (status === GameStatus.PLAYING) {
      const interval = setInterval(() => {
        const { currentWpm } = calculateStats();
        setWpm(currentWpm);

        // Ghost Logic
        if (settings.ghostMode && lastWpm > 0 && startTime) {
           const elapsedMin = (Date.now() - startTime) / 60000;
           // ghost chars = wpm * 5 * minutes
           const gIdx = Math.min(quote.text.length, elapsedMin * lastWpm * 5);
           setGhostIndex(gIdx);
        }

      }, 100);
      return () => clearInterval(interval);
    }
  }, [status, calculateStats, settings.ghostMode, lastWpm, startTime, quote.text.length]);

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    if (status === GameStatus.COMPLETED) return;

    const val = e.target.value;

    // Start timer on first char
    if (status === GameStatus.IDLE && val.length > 0) {
      setStartTime(Date.now());
      setStatus(GameStatus.PLAYING);
    }

    setInput(val);

    // Check completion
    if (val.length === quote.text.length) {
      const isPerfect = val === quote.text;
      setEndTime(Date.now());

      if (isPerfect) {
        setStatus(GameStatus.COMPLETED);
        const finalTime = Date.now();
        const durationMins = (finalTime - (startTime || finalTime)) / 60000;
        const finalWpm = Math.round((quote.text.length / 5) / (durationMins || 1));
        setWpm(finalWpm);
      } else {
        setStatus(GameStatus.FAILED);
        onFail();
      }
    }
  };

  const handleRetry = () => {
    setInput('');
    setStartTime(null);
    setEndTime(null);
    setStatus(GameStatus.IDLE);
    setWpm(0);
    setGhostIndex(0);
    setIsFocused(true);
    inputRef.current?.focus();
  };

  const handleNext = () => {
    const xp = calculateXP(wpm, quote.text.length);
    onComplete(xp, wpm);
  };

  const renderText = () => {
    const currentWordIndex = wordBoundaries.findIndex(w => input.length >= w.start && input.length < w.end);
    // If we are exactly at the end of a word (on a space), we might be "between" words. 
    // Logic: If input.length is at a space, currentWordIndex might be -1.
    // Read Ahead Logic:
    // Hide current word (opacity 0 or transparent color)
    // Highlight next word

    return quote.text.split('').map((char, index) => {
      let colorClass = 'text-stone-300'; // Default / Untyped
      let bgClass = '';
      let extraClass = '';

      // Determine if character is part of current, next, or other words
      const isInCurrentWord = currentWordIndex !== -1 && index >= wordBoundaries[currentWordIndex].start && index < wordBoundaries[currentWordIndex].end;

      const nextWordIdx = currentWordIndex + 1;
      const isInNextWord = currentWordIndex !== -1 && nextWordIdx < wordBoundaries.length && index >= wordBoundaries[nextWordIdx].start && index < wordBoundaries[nextWordIdx].end;

      // Typed characters
      if (index < input.length) {
        if (input[index] === char) {
          colorClass = 'text-frog-800';
        } else {
          colorClass = 'text-red-500 bg-red-100';
        }
      }

      // Read Ahead Mode Logic
      if (settings.readAheadMode && status === GameStatus.PLAYING) {
         if (isInCurrentWord && index >= input.length) {
            // Hide untyped characters of the current word
            colorClass = 'text-transparent bg-stone-100 rounded-sm'; 
         }
         if (isInNextWord) {
            // Highlight next word
            bgClass = 'bg-yellow-100 rounded-sm';
            if (index >= input.length) colorClass = 'text-stone-800 font-bold';
         }
      }

      return (
        <span key={index} className={`relative ${colorClass} ${bgClass} ${extraClass} transition-colors duration-100`}>
          {char}
          {/* Ghost Cursor Rendering */}
          {settings.ghostMode && status === GameStatus.PLAYING && Math.floor(ghostIndex) === index && (
             <span className="absolute -top-6 left-0 text-lg opacity-60 transition-all duration-300 transform -translate-x-1/2">
               👻
             </span>
          )}
        </span>
      );
    });
  };

  return (
    <div 
      className="relative w-full max-w-3xl mx-auto min-h-[280px] flex flex-col"
      ref={containerRef}
    >
      {/* Focus Overlay */}
      {!isFocused && (
        <div 
          onClick={handleFocus}
          className="absolute inset-0 z-50 flex items-center justify-center bg-white/60 backdrop-blur-[2px] cursor-pointer rounded-3xl border-2 border-dashed border-frog-200/50 hover:border-frog-300 transition-all"
        >
          <div className="text-center animate-bounce text-frog-500">
            <Play className="w-8 h-8 mx-auto mb-2 opacity-80" fill="currentColor" />
            <span className="font-bold text-sm tracking-wide uppercase">Click or Type to Start</span>
          </div>
        </div>
      )}

      {/* Main Game Area */}
      <div className={`
        relative flex-grow flex flex-col justify-center p-8 md:p-12 bg-white rounded-3xl shadow-[0_8px_30px_rgb(0,0,0,0.04)] transition-all duration-300
        ${!isFocused ? 'blur-[1px] opacity-50' : ''}
        ${status === GameStatus.FAILED ? 'ring-2 ring-red-100' : ''}
        ${status === GameStatus.COMPLETED ? 'ring-2 ring-frog-100 bg-frog-50/30' : ''}
        ${streak > 5 && status === GameStatus.PLAYING ? 'shadow-[0_0_30px_rgba(250,204,21,0.2)] ring-1 ring-yellow-200/50' : ''}
      `}>

        {/* Source Header */}
        <div className="absolute top-6 left-8 right-8 flex justify-between text-[10px] font-bold text-stone-300 uppercase tracking-widest select-none">
          <span>{quote.source}</span>
          <span>{quote.author}</span>
        </div>

        {/* Text Display */}
        <div 
          className="font-mono text-2xl md:text-3xl leading-relaxed break-words mb-10 mt-4 relative z-10 outline-none select-none"
          onClick={handleFocus}
        >
          {renderText()}
          {/* Custom Blinking Cursor */}
          {status !== GameStatus.COMPLETED && status !== GameStatus.FAILED && isFocused && input.length < quote.text.length && (
            <span className="caret-blink w-[3px] h-[1em] bg-frog-400 inline-block align-middle ml-[1px] translate-y-[-2px] rounded-full"></span>
          )}
        </div>

        {/* Hidden Input */}
        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          onBlur={handleBlur}
          onFocus={() => setIsFocused(true)}
          className="absolute opacity-0 top-0 left-0 h-full w-full cursor-default resize-none caret-transparent"
          autoFocus={isFocused}
          disabled={status === GameStatus.COMPLETED || status === GameStatus.FAILED}
        />

        {/* Status Bar */}
        <div className="absolute bottom-6 left-8 right-8 flex justify-between items-end select-none">
           <div className="flex items-center gap-6 text-stone-400 font-mono text-xs">
             <div className="flex flex-col">
                <span className="text-[9px] uppercase font-bold text-stone-300 mb-0.5">Speed</span>
                <span className="font-bold text-base text-stone-600">{wpm} <span className="text-[10px] font-normal">WPM</span></span>
             </div>
             {status === GameStatus.COMPLETED && (
                 <div className="flex flex-col animate-pulse text-frog-600">
                    <span className="text-[9px] uppercase font-bold text-frog-400 mb-0.5">XP Earned</span>
                    <span className="font-bold text-base">+{calculateXP(wpm, quote.text.length)}</span>
                 </div>
             )}
             {settings.ghostMode && lastWpm > 0 && status === GameStatus.PLAYING && (
                 <div className="flex flex-col opacity-50">
                    <span className="text-[9px] uppercase font-bold text-stone-300 mb-0.5">Ghost</span>
                    <span className="font-bold text-base text-purple-300">{lastWpm} <span className="text-[10px] font-normal">WPM</span></span>
                 </div>
             )}
           </div>

           <div>
              {status === GameStatus.FAILED && (
                <button 
                  onClick={handleRetry}
                  className="flex items-center gap-2 px-4 py-1.5 bg-red-50 text-red-500 rounded-full hover:bg-red-100 transition font-bold text-xs tracking-wide"
                >
                  <RotateCcw className="w-3 h-3" /> Retry
                </button>
              )}
              {status === GameStatus.COMPLETED && (
                <button 
                  onClick={handleNext}
                  className="flex items-center gap-2 px-5 py-2 bg-frog-500 text-white rounded-full hover:bg-frog-600 transition shadow-lg shadow-frog-200/50 font-bold text-xs tracking-wide"
                >
                  Next Quote <Award className="w-3 h-3" />
                </button>
              )}
           </div>
        </div>
      </div>

      <div className="text-center mt-4 h-4 text-stone-300 text-[10px] transition-opacity duration-500">
        {status === GameStatus.FAILED ? <span className="text-red-300">100% Accuracy Required. Streak Reset.</span> : 
         status === GameStatus.COMPLETED ? <span className="text-frog-400">Perfect! Streak Increased.</span> :
         settings.readAheadMode && isFocused ? "Read Ahead Mode: Memorize the hidden words." :
         isFocused ? "Type the quote above exactly." : ""}
      </div>
    </div>
  );
};

export default TypingArea;
